{"query": "
SELECT
 (SELECT COUNT(DISTINCT Gene) FROM rna_tissue_consensus) AS total_genes,
 (SELECT COUNT(*) FROM rna_tissue_consensus WHERE Tissue='pancreas') AS panc_rows,
 (SELECT COUNT(*) FROM rna_tissue_consensus WHERE Tissue='kidney') AS kid_rows;
"}

