) x;
"}

{"query": "
SELECT DISTINCT regexp_extract("RNA tissue specific nTPM", '^([^:]+):', 1) AS tissue
FROM proteinatlas
WHERE lower("RNA tissue specific nTPM") LIKE '%pancrea%' OR lower("RNA tissue specific nTPM") LIKE '%kidney%';
"}

